function esc(value) { return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function faqSchema(items) { return `<script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: items.map(([name, text]) => ({ '@type': 'Question', name, acceptedAnswer: { '@type': 'Answer', text } })) })}</script>`; }
function shell({ title, description, slug, faq, body }) { return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>${esc(title)} | Alex Does Digital</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="https://alxdoesdigital.com/${slug}"><meta property="og:type" content="article"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="https://alxdoesdigital.com/${slug}"><meta property="og:image" content="https://alxdoesdigital.com/images/alexpolo-copy.webp"><meta property="article:published_time" content="2026-10-09">${faqSchema(faq)}</head><body><main>${body}</main></body></html>\n`; }

function hubFaq() { return [['How do financial advisors generate qualified leads?', 'Define the client and planning needs the firm can serve, build verifiable trust, capture relevant demand through search and education, qualify carefully, follow up consistently, and measure attended appointments and suitable opportunities.'], ['Which marketing channel works best for financial advisors?', 'Google Ads can capture active searches, Facebook and Instagram can build familiarity through useful education, and SEO can create durable discovery. The best starting channel depends on the audience, market, offer, compliance process, website, budget, and follow-up capacity.'], ['What should financial advisor marketing measure?', 'Measure relevant demand, suitable leads, booked and attended appointments, qualified opportunities, signed relationships where appropriate, acquisition cost, time to outcome, and lost reasons.'], ['How should compliance fit into financial advisor marketing?', 'The firm should define an approval, disclosure, supervision, recordkeeping, and review process based on its registrations, services, jurisdictions, and applicable rules before campaigns launch.']]; }

function clusterCards(current) {
  const cards = [[cluster.google, 'Google Ads', 'Google Ads for Financial Advisors', 'Keywords, negatives, compliant copy, landing pages, budgets, and client-outcome tracking.'], [cluster.facebook, 'Facebook Ads', 'Facebook Lead Generation for Financial Advisors', 'Educational offers, trust-building creative, lead forms, follow-up, and appointment quality.'], [cluster.seo, 'SEO', 'SEO for Financial Advisors', 'Local SEO, service pages, expertise content, technical foundations, authority, and AI visibility.']].filter(([slug]) => slug !== current);
  return `<section class="cluster-navigation"><p class="eyebrow">Financial advisor marketing cluster</p><h2>Continue with the most relevant next step</h2><div class="topic-hub-grid">${cards.map(([slug, label, title, copy]) => `<a class="topic-hub-card" href="/${slug}"><span>${label}</span><h3>${title}</h3><p>${copy}</p><strong>Explore this page →</strong></a>`).join('')}</div></section>`;
}

